            <StepFooter>
              <Button variant="ghost" size="sm" onClick={() => setStep(0)}><ArrowLeft /> Back</Button>
              <Button variant="cta" size="sm" onClick={() => setStep(2)}>Proceed to notify <ArrowRight /></Button>
            </StepFooter>
          </div>
