  typeof crypto !== "undefined" && crypto.randomUUID
    ? crypto.randomUUID()
    : "h-" + Math.random().toString(36).slice(2) + Date.now().toString(36);
const nowISO = () => new Date().toISOString();
const dispatch = (evt) => {
  try {
    window.dispatchEvent(new Event(evt));
  } catch {
    // ignore
  }
};

